<?php
$year=(int)($_GET['year']??date('Y'));if($year<2000||$year>2200)$year=(int)date('Y');
$balances=[];foreach(chr_rows($pdo,'leave_policy') as $policy){if($policy['status']!=='Published')continue;$type=$policy['values']['type'];$allocated=chr_entitlement($pdo,$owner,$type,$year)??0;$used=chr_used($pdo,$owner,$type,$year);$q=$pdo->prepare("SELECT * FROM hr_requests WHERE user_id=? AND kind='leave' AND category=? AND status='Pending'");$q->execute([$owner,$type]);$pending=0;foreach($q as $request)foreach(chr_request_days($pdo,$request) as $day)if((int)substr($day['leave_date'],0,4)===$year)$pending+=(float)$day['units'];$balances[]=['type'=>$policy['title'],'allocated'=>$allocated,'used'=>$used,'pending'=>$pending,'available'=>$allocated-$used];}
?>
<div class="ess-section-heading ess-toolbar"><form class="work-form ess-filter"><input type="hidden" name="page" value="leaves"><label>Leave year<input type="number" name="year" min="2000" max="2200" value="<?=$year?>"></label><button class="primary">Apply</button></form><button class="primary" data-dialog-open="leave-dialog">+ Apply leave</button></div>
<div class="ess-metrics"><?php foreach(['Allocated days'=>array_sum(array_column($balances,'allocated')),'Used days'=>array_sum(array_column($balances,'used')),'Pending days'=>array_sum(array_column($balances,'pending')),'Available days'=>array_sum(array_column($balances,'available'))] as $label=>$value):?><section class="panel"><small><?=h($label)?></small><h2><?=$value?></h2></section><?php endforeach;?></div>
<section class="panel"><h2>Leave balance · <?=$year?></h2><?php ess_table(['type'=>'Leave type','allocated'=>'Allocated','used'=>'Used','pending'=>'Pending','available'=>'Available'],$balances);?><p class="ess-hint">Pending requests do not reserve balance.</p></section>
<?php $requestKind='leave';$requestFrom=$year.'-01-01';$requestTo=$year.'-12-31';require __DIR__.'/requests-list.php';$dialogKind='leave';require __DIR__.'/request-dialog.php';?>
